function createLayer(fillVal) {
  // allocate new array layer
  let layer = [];
  for (let x = 0; x < g_WORLDX; x++) {
    // allocate new row layer
    let row = [];
    for (let z = 0; z < g_WORLDZ; z++) {
      row.push(fillVal);
    }
    layer.push(row);
  }
  return layer;
}

function createGoldLayer(inputLayer) {
  // allocate new array layer
  let layer = [],
      goldX = Math.floor(Math.random() * g_WORLDX),
      goldZ = Math.floor(Math.random() * g_WORLDZ);
  for (let x = 0; x < g_WORLDX; x++) {
    // allocate new row layer
    let row = [];
    for (let z = 0; z < g_WORLDZ; z++) {
      row.push(
        (goldX == x && goldZ == z) ? 1 : 0
      );
    }
    layer.push(row);
  }
  // replace input layer with air
  inputLayer[goldX][goldZ] = 0;
  return layer;
}

function drawMap() {
  for (let y = 0; y < g_WORLDY; y++) {
    let yDirtLayer = g_groundMap[y],
        yGoldLayer = g_goldMap[y];
    for (let x = 0; x < g_WORLDX; x++) {
      for (let z = 0; z < g_WORLDZ; z++) {
        const isGoldBlock = yGoldLayer[x][z] == 1;
        if (isGoldBlock || yDirtLayer[x][z] >= 1) {
          const block = new Cube();
          block.color = [0.0, 0.0, 0.0, 0.0];
          block.matrix.translate(
            x - (g_WORLDX / 2),
            y - 0.7,
            z - (g_WORLDZ / 2)
          );

          // set texture num
          if (isGoldBlock) block.textureNum = g_GOLDTEXNUM;
          else if (yDirtLayer[x][z] == g_STONEMAPNUM) block.textureNum = g_STONETEXNUM;
          else if (yDirtLayer[x][z] == g_DIRTMAPNUM) block.textureNum = g_DIRTTEXNUM;
          else if (yDirtLayer[x][z] == g_GRASSMAPNUM) block.textureNum = g_GRASSTEXNUM;
          else if (yDirtLayer[x][z] == g_LEAVESMAPNUM) block.textureNum = g_LEAVESTEXNUM;
          else if (yDirtLayer[x][z] == g_GLASSMAPNUM) block.textureNum = g_GLASSTEXNUM;
          else if (yDirtLayer[x][z] == g_LUCKYMAPNUM) block.textureNum = g_LUCKYTEXNUM;
          else if (yDirtLayer[x][z] == g_UNKNOWNMAPNUM) block.textureNum = g_UNKNOWNTEXNUM;
          else {
            block.textureNum = -2;
            if (yDirtLayer[x][z] == g_PINKMAPNUM) block.color = [0.95, 0.57, 1.0, 1.0];
            else if (yDirtLayer[x][z] == g_MAROONMAPNUM) block.color = [0.59, 0.06, 0.05, 1.0];
          }

          block.render();
        }
      }
    }
  }
}

function raycast(eventButton) {
  const maxDistance = 6, step = 0.1;
  const origin = g_camera.eye,
        dir = g_camera.getLookDirection();

  let lastEmpty = null;
  for (let t = 0; t < maxDistance; t += step) {
    let worldX = origin.elements[0] + dir.elements[0] * t;
    let worldY = origin.elements[1] + dir.elements[1] * t;
    let worldZ = origin.elements[2] + dir.elements[2] * t;

    let mapX = Math.floor(worldX + g_WORLDX / 2);
    let mapY = Math.floor(worldY + 0.75);
    let mapZ = Math.floor(worldZ + g_WORLDZ / 2);

    if (
      mapX >= 0 && mapX < g_WORLDX &&
      mapY >= 0 && mapY < g_WORLDY &&
      mapZ >= 0 && mapZ < g_WORLDZ
    ) {
      if (
        eventButton === 0 && (
          g_groundMap[mapY][mapX][mapZ] >= 1 ||
          g_goldMap[mapY][mapX][mapZ] === 1
        )
      ) {
        if (g_goldMap[mapY][mapX][mapZ]) goldIndicator.innerHTML++;
        g_groundMap[mapY][mapX][mapZ] = g_AIRMAPNUM;
        g_goldMap[mapY][mapX][mapZ] = g_AIRMAPNUM;
        return;
      }
      if (g_groundMap[mapY][mapX][mapZ] >= 1 && eventButton === 2) {
          return lastEmpty;
        } else {
          lastEmpty = { mapX, mapY, mapZ };
      }
    }
  }
  return null;
}